    }

    /**
     * Known country codes (digits after the {@code '+'}), longest first so {@code '61'} is
     * matched before {@code '1'}, mirroring {@code NormalizeOwnerTelephone}.
     */
    private static final String[] COUNTRY_CODES = {"61", "1"};

